```json
"schema": {
  "anyOf": [
    {
      "$ref": "#/components/schemas/Cat"
    },
    {
      "$ref": "#/components/schemas/Dog"
    }
  ],
  "discriminator": {
    "propertyName": "type"
  },
  "title": "Pet"
}
```

